function isPalindrome(s) {
  const dq = [...s];               // the letters, front to back
  let head = 0;                    // JavaScript has no deque: an index marks the front
  while (dq.length - head > 1) {
    const first = dq[head++];      // remove from the front
    const last = dq.pop();         // remove from the back
    if (first !== last) return false;
  }
  return true;
}

from collections import deque

def is_palindrome(s: str) -> bool:
    dq = deque(s)                     # the letters, front to back
    while len(dq) > 1:
        first = dq.popleft()          # remove from the front
        last = dq.pop()               # remove from the back
        if first != last:
            return False
    return True

boolean isPalindrome(String s) {
    Deque<Character> dq = new ArrayDeque<>();
    for (char c : s.toCharArray()) dq.addLast(c);   // the letters, front to back
    while (dq.size() > 1) {
        char first = dq.pollFirst();                // remove from the front
        char last = dq.pollLast();                  // remove from the back
        if (first != last) return false;
    }
    return true;
}

bool isPalindrome(const string& s) {
    deque<char> dq(s.begin(), s.end());   // the letters, front to back
    while (dq.size() > 1) {
        char first = dq.front();          // remove from the front
        dq.pop_front();
        char last = dq.back();            // remove from the back
        dq.pop_back();
        if (first != last) return false;
    }
    return true;
}
